        this.loadBookmarkTagCounts(DataSource_BookmarksBase.cachedBookmarkTagCounts);
      let url = "/ajax/user/" + this.viewingUserId + "/illusts/bookmark/tags";
      let result = await helpers.pixivRequest.get(url, {});
